"""F3.1.0 target-free structural audit: Sentinel Historical 2022-2024 + Topography Basic."""
from pathlib import Path
import json,warnings
import numpy as np,pandas as pd
import matplotlib.pyplot as plt,seaborn as sns
from scipy.stats import spearmanr,pearsonr,ks_2samp
warnings.filterwarnings('ignore');sns.set_theme(style='whitegrid')
ROOT=Path(__file__).resolve().parents[2];SRC=ROOT/'data/processed/family_1';BASE=ROOT/'outputs/modeling/family_3/f3_1_0_structural_audit';T=BASE/'tables';F=BASE/'figures';R=BASE/'report'
for p in [T,F,R]:p.mkdir(parents=True,exist_ok=True)
ID='ID_POLIGONO';IND=['ndvi','evi','lai','fapar','savi','ndwi','msi','nddi'];FAM={'ndvi':'vigor','evi':'vigor','lai':'vigor','fapar':'vigor','savi':'vigor_soil_adjusted','ndwi':'moisture','msi':'moisture_stress_ratio','nddi':'drought_ratio'}
def safe_corr(a,b,kind='spearman'):
 z=pd.DataFrame({'a':a,'b':b}).replace([np.inf,-np.inf],np.nan).dropna();return (spearmanr(z.a,z.b).statistic if kind=='spearman' else pearsonr(z.a,z.b).statistic) if len(z)>3 and z.a.nunique()>1 and z.b.nunique()>1 else np.nan
def main():
 s=pd.read_parquet(SRC/'timeseries/sentinel_timeseries.parquet');h=s[s.is_history_2022_2024.astype(bool)&s.year.isin([2022,2023,2024])].copy();hf=pd.read_parquet(SRC/'features/history_features.parquet');top=pd.read_parquet(SRC/'features/topography_basic_features.parquet');cl=pd.read_parquet(SRC/'environment/climate_monthly_timeseries.parquet');groups=s[[ID,'CONJUNTO']].drop_duplicates().set_index(ID).CONJUNTO;hf['CONJUNTO']=hf[ID].map(groups);top['CONJUNTO']=top[ID].map(groups)
 assert h.year.max()==2024 and h.year.min()==2022 and h[ID].nunique()==197 and groups.value_counts().to_dict()=={'ENTRENAMIENTO':138,'PREDICCION':59}
 histcols=[c for c in hf if c.startswith('HIST_S2_')];topcols=[c for c in top if c.startswith('TOPO_BASIC_')];eligible=hf[[ID,'CONJUNTO']+histcols].merge(top[[ID]+topcols],on=ID,validate='one_to_one')
 # Inventory and traceability.
 inv=[]
 for c in histcols:
  p=c.replace('HIST_S2_','');idx=next((x for x in IND if p.startswith(x+'_')),p);stat=p[len(idx)+1:];inv.append({'feature':c,'block':'Sentinel Historical','source_file':'history_features.parquet','original_source':'sentinel_timeseries.parquet','sensor':'Sentinel-2','index_or_variable':idx,'statistic':stat,'period':'Apr-Oct 2022-2024','transformation':'monthly parcel baseline then interannual summary','n_available':eligible[c].notna().sum(),'derived':True,'conceptual_family':FAM.get(idx,'other')})
 for c in topcols:
  v='elevation' if 'elevation' in c else ('slope' if 'slope' in c else 'terrain');inv.append({'feature':c,'block':'Topography Basic','source_file':'topography_basic_features.parquet','original_source':'INEGI CEM4 120m elevation/slope rasters','sensor':'DEM_OR_SLOPE','index_or_variable':v,'statistic':c.split('_')[-1],'period':'STATIC','transformation':'fractionally weighted zonal statistic','n_available':eligible[c].notna().sum(),'derived':True,'conceptual_family':'topography'})
 pd.DataFrame(inv).to_csv(T/'01_structural_variable_inventory.csv',index=False)
 # Quality of derived matrix.
 qual=[]
 for c in histcols+topcols:
  x=eligible[c].replace([np.inf,-np.inf],np.nan);tr=x[eligible.CONJUNTO.eq('ENTRENAMIENTO')];pr=x[eligible.CONJUNTO.eq('PREDICCION')];iq=tr.quantile(.75)-tr.quantile(.25);qual.append({'feature':c,'block':'Sentinel Historical' if c in histcols else 'Topography Basic','missing_all_pct':x.isna().mean()*100,'missing_train_pct':tr.isna().mean()*100,'missing_prediction_pct':pr.isna().mean()*100,'n_unique':x.nunique(),'variance':x.var(),'min':x.min(),'q01':x.quantile(.01),'median':x.median(),'q99':x.quantile(.99),'max':x.max(),'iqr':iq,'constant':x.nunique()<=1,'near_zero_variance':x.var()<1e-10,'nonfinite_original':np.isinf(eligible[c]).sum()})
 qdf=pd.DataFrame(qual);qdf.to_csv(T/'02_variable_quality.csv',index=False)
 # Raw observation coverage, timing and cloud.
 rows=[]
 for (pid,grp,yr),z in h.groupby([ID,'CONJUNTO','year']):
  r={ID:pid,'CONJUNTO':grp,'year':yr,'n_calendar_rows':len(z),'n_cloud_lt100':(z.cloud_raw<100).sum(),'cloud_mean':z.cloud_raw.mean(),'cloud_median':z.cloud_raw.median(),'first_date':z.fecha_captura.min(),'last_date':z.fecha_captura.max()}
  for idx in IND:r[f'n_valid_{idx}']=z[f'{idx}_promedio'].notna().sum()
  rows.append(r)
 cov=pd.DataFrame(rows);cov.to_csv(T/'03_coverage_by_parcel_year.csv',index=False);h.groupby(['CONJUNTO','year','month']).agg(rows=(ID,'size'),parcels=(ID,'nunique'),valid_ndvi=('ndvi_promedio','count'),cloud_mean=('cloud_raw','mean'),cloud_100=('cloud_is_100','mean')).reset_index().to_csv(T/'04_temporal_coverage.csv',index=False);h.groupby(['CONJUNTO','year']).cloud_raw.describe().reset_index().to_csv(T/'05_cloud_summary.csv',index=False)
 # Annual satellite summaries and persistence (Apr-Oct, spatial means only).
 cyc=h[h.month.between(4,10)];ann=cyc.groupby([ID,'CONJUNTO','year'])[[f'{i}_promedio' for i in IND]].mean().reset_index();ann.to_csv(T/'06_annual_structural_summaries.csv',index=False);pers=[];wb=[]
 for idx in IND:
  c=f'{idx}_promedio';w=ann.pivot(index=ID,columns='year',values=c)
  for a,b in [(2022,2023),(2022,2024),(2023,2024)]:pers.append({'index':idx,'year_a':a,'year_b':b,'spearman_all':safe_corr(w[a],w[b]),'pearson_all':safe_corr(w[a],w[b],'pearson'),'n_complete':w[[a,b]].dropna().shape[0]})
  pm=ann.groupby(ID)[c].mean();within=ann.groupby(ID)[c].std().mean();between=pm.std();wb.append({'index':idx,'mean_within_parcel_sd':within,'between_parcel_sd_of_means':between,'between_to_within_ratio':between/within if within else np.nan,'median_years_available':ann.groupby(ID)[c].count().median()})
 pd.DataFrame(pers).to_csv(T/'07_annual_rank_persistence.csv',index=False);pd.DataFrame(wb).to_csv(T/'08_within_between_variability.csv',index=False)
 # Redundancy and effective rank without fitting a latent model.
 X=eligible[histcols+topcols].replace([np.inf,-np.inf],np.nan);Xi=X.fillna(X.median());pear=Xi.corr();spear=Xi.corr(method='spearman');pairs=[]
 for i,a in enumerate(Xi):
  for b in Xi.columns[i+1:]:pairs.append({'feature_a':a,'feature_b':b,'block_a':'history' if a in histcols else 'topography','block_b':'history' if b in histcols else 'topography','pearson':pear.loc[a,b],'spearman':spear.loc[a,b],'abs_pearson':abs(pear.loc[a,b]),'abs_spearman':abs(spear.loc[a,b])})
 pairs=pd.DataFrame(pairs).sort_values('abs_spearman',ascending=False);pairs.to_csv(T/'09_redundancy_pairs.csv',index=False);Z=(Xi-Xi.mean())/Xi.std().replace(0,1);sv=np.linalg.svd(Z,compute_uv=False);ev=sv**2/(sv**2).sum();pd.DataFrame([{'n_features':Xi.shape[1],'matrix_rank':np.linalg.matrix_rank(Z),'participation_ratio_effective_dimension':1/(ev**2).sum(),'components_for_80pct_singular_energy':int(np.searchsorted(np.cumsum(ev),.8)+1),'components_for_90pct_singular_energy':int(np.searchsorted(np.cumsum(ev),.9)+1),'components_for_95pct_singular_energy':int(np.searchsorted(np.cumsum(ev),.95)+1)}]).to_csv(T/'10_effective_dimensionality.csv',index=False)
 # Historical climate confounding, auxiliary only.
 ch=cl[cl.is_history_2022_2024.astype(bool)&cl.year.isin([2022,2023,2024])&cl.month.between(4,10)].groupby([ID,'year'])[['precip_mean','tmin_mean','tmax_mean','tmean_mean','dtr_mean']].mean().reset_index();ac=ann.merge(ch,on=[ID,'year']);cr=[]
 for i in IND:
  for c in ['precip_mean','tmin_mean','tmax_mean','tmean_mean','dtr_mean']:cr.append({'satellite_index':i,'climate_variable':c,'spearman_parcel_year':safe_corr(ac[f'{i}_promedio'],ac[c]),'n':ac[[f'{i}_promedio',c]].dropna().shape[0]})
 pd.DataFrame(cr).to_csv(T/'11_historical_climate_confounding.csv',index=False)
 # Train vs prediction target-free comparability.
 comp=[];oor=[]
 for c in histcols+topcols:
  a=eligible.loc[eligible.CONJUNTO.eq('ENTRENAMIENTO'),c].dropna();b=eligible.loc[eligible.CONJUNTO.eq('PREDICCION'),c].dropna();sd=np.sqrt((a.var()+b.var())/2);comp.append({'feature':c,'block':'history' if c in histcols else 'topography','train_mean':a.mean(),'prediction_mean':b.mean(),'standardized_mean_difference':(b.mean()-a.mean())/sd if sd else 0,'ks_statistic':ks_2samp(a,b).statistic if len(a) and len(b) else np.nan,'missing_delta_prediction_minus_train':eligible.loc[eligible.CONJUNTO.eq('PREDICCION'),c].isna().mean()-eligible.loc[eligible.CONJUNTO.eq('ENTRENAMIENTO'),c].isna().mean()});oor.append({'feature':c,'train_min':a.min(),'train_max':a.max(),'prediction_below_train_n':(b<a.min()).sum(),'prediction_above_train_n':(b>a.max()).sum(),'prediction_outside_pct':((b<a.min())|(b>a.max())).mean()*100})
 comp=pd.DataFrame(comp).sort_values('ks_statistic',ascending=False);comp.to_csv(T/'12_train_prediction_comparison.csv',index=False);pd.DataFrame(oor).sort_values('prediction_outside_pct',ascending=False).to_csv(T/'13_prediction_out_of_range.csv',index=False);qdf[qdf.block.eq('Topography Basic')].to_csv(T/'14_topography_audit.csv',index=False)
 # Numerical ratio diagnostics.
 nd=[]
 for i in ['msi','nddi']:
  x=h[f'{i}_promedio'];nd.append({'index':i,'n_valid':x.notna().sum(),'nonfinite':np.isinf(x).sum(),'abs_gt_5':(x.abs()>5).sum(),'abs_gt_10':(x.abs()>10).sum(),'q001':x.quantile(.001),'q999':x.quantile(.999)})
 pd.DataFrame(nd).to_csv(T/'15_ratio_index_instability.csv',index=False)
 # Figures.
 plt.figure(figsize=(10,7));sns.heatmap(spear,center=0,cmap='vlag',xticklabels=False,yticklabels=False);plt.tight_layout();plt.savefig(F/'01_structural_spearman_heatmap.png',dpi=180);plt.close();
 plt.figure(figsize=(8,4));sns.boxplot(cov.melt(id_vars=['CONJUNTO','year'],value_vars=[f'n_valid_{i}' for i in IND]),x='variable',y='value',hue='CONJUNTO');plt.xticks(rotation=35);plt.tight_layout();plt.savefig(F/'02_historical_coverage.png',dpi=180);plt.close();
 plt.figure(figsize=(7,4));sns.barplot(pd.DataFrame(pers),x='index',y='spearman_all',hue='year_b');plt.axhline(0,color='black');plt.tight_layout();plt.savefig(F/'03_annual_persistence.png',dpi=180);plt.close();
 plt.figure(figsize=(7,4));sns.barplot(pd.DataFrame(wb),x='index',y='between_to_within_ratio');plt.tight_layout();plt.savefig(F/'04_between_within_ratio.png',dpi=180);plt.close();
 plt.figure(figsize=(8,4));sns.scatterplot(comp,x='standardized_mean_difference',y='ks_statistic',hue='block');plt.axvline(0,color='black');plt.tight_layout();plt.savefig(F/'05_train_prediction_comparability.png',dpi=180);plt.close();
 tlong=top.melt(id_vars=['CONJUNTO'],value_vars=['TOPO_BASIC_elevation_mean','TOPO_BASIC_slope_mean']);plt.figure(figsize=(8,4));sns.boxplot(tlong,x='variable',y='value',hue='CONJUNTO');plt.yscale('symlog');plt.tight_layout();plt.savefig(F/'06_topography_distributions.png',dpi=180);plt.close();
 plt.figure(figsize=(8,4));sns.histplot(h,x='cloud_raw',hue='CONJUNTO',element='step',stat='density',common_norm=False);plt.tight_layout();plt.savefig(F/'07_cloud_distribution.png',dpi=180);plt.close();
 plt.figure(figsize=(8,4));sns.barplot(pd.DataFrame(cr).assign(a=lambda x:x.spearman_parcel_year.abs()).sort_values('a',ascending=False).head(15),x='a',y='satellite_index',hue='climate_variable');plt.tight_layout();plt.savefig(F/'08_climate_confounding.png',dpi=180);plt.close()
 report(pd.DataFrame(inv),qdf,cov,pd.DataFrame(pers),pd.DataFrame(wb),pairs,comp,pd.DataFrame(oor),pd.DataFrame(nd))
def report(inv,q,cov,pers,wb,pairs,comp,oor,nd):
 ed=pd.read_csv(T/'10_effective_dimensionality.csv').iloc[0];hp=pairs[pairs.abs_spearman>=.9];stable=pers.groupby('index').spearman_all.mean().sort_values(ascending=False);shift=comp[comp.standardized_mean_difference.abs()>=.5];missing=q[q.missing_all_pct>0];const=q[q.constant];out=oor[oor.prediction_outside_pct>0];txt=f'''# F3.1.0 — Structural Data Audit\n\n## 1. Resumen ejecutivo\n**Resultado observado:** existen 197 parcelas (138 TRAIN, 59 PREDICTION), 24 features Sentinel Historical y 25 Topography Basic. La matriz tiene rango {int(ed.matrix_rank)}, pero dimensión efectiva por participation ratio ≈{ed.participation_ratio_effective_dimension:.1f}; {int(ed.components_for_90pct_singular_energy)} direcciones concentran 90% de la energía estandarizada. Esto evidencia redundancia fuerte, no justifica todavía un número de factores.\n\n**Conclusión metodológica:** sí hay información suficiente para intentar una representación latente target-free, pero debe equilibrarse por bloques y separar nivel histórico, variabilidad/cobertura y topografía. La persistencia espectral es descriptiva y no prueba suelo ni capacidad productiva.\n\n## 2. Inventario y trazabilidad\n- Sentinel original: `sentinel_timeseries.parquet`, filtrado exclusivamente por `is_history_2022_2024` y años 2022–2024.\n- Features: 8 índices × `mean`, `std`, `months`, ventana abril–octubre 2022–2024. `std` del feature es variación de baselines mensuales; no debe confundirse con el `*_std` espacial de cada captura.\n- Topography Basic: 25 estadísticas zonales estáticas de elevación/pendiente a 120 m.\n- Climate Historical sólo se usó como diagnóstico auxiliar de confusión. Yield y Climate Current 2025 no se cargaron.\n\n## 3. Calidad y cobertura\nFeatures con missing: {len(missing)}; constantes: {len(const)}. Cobertura mediana anual NDVI={cov.n_valid_ndvi.median():.0f} observaciones. Los conteos y nubosidad varían por parcela/año, de modo que `months` y algunos `std` pueden reflejar disponibilidad además de comportamiento. Cocientes MSI/NDDI: {nd.round(3).to_dict('records')}. No se eliminaron outliers.\n\n## 4. Redundancia\nHay {len(hp)} pares con |Spearman|≥0.90. Los bloques dominantes son estadísticas vecinas del mismo índice y cuantiles topográficos. Una familia de vigor con múltiples índices casi equivalentes podría dominar una representación conjunta por conteo de columnas. Ver `09_redundancy_pairs.csv`.\n\n## 5. Persistencia temporal\nPromedio de correlación de rangos interanual: {stable.round(3).to_dict()}. Ratios between/within: {wb.set_index('index').between_to_within_ratio.round(3).to_dict()}. Son recurrencias relativas; años, cobertura, clima y manejo siguen mezclados. Las asociaciones con clima histórico se documentan en `11_historical_climate_confounding.csv` y no son causales.\n\n## 6. Topografía\nEs estática y completa según `14_topography_audit.csv`, pero contiene muchas estadísticas redundantes de dos superficies. Elevación y pendiente operan en escalas muy distintas: cualquier análisis conjunto requerirá escalamiento fold-safe en fases predictivas. No se incluyó Topography Advanced.\n\n## 7. TRAIN vs PREDICTION\nVariables con |SMD|≥0.5: {len(shift)}. Variables con valores PREDICTION fuera del rango TRAIN: {len(out)}. Mayores diferencias: {comp.head(10)[['feature','standardized_mean_difference','ks_statistic','missing_delta_prediction_minus_train']].round(3).to_dict('records')}. Esto señala riesgo potencial, no demuestra shift.\n\n## 8. Riesgos\nCobertura desigual; nubosidad; índices cociente; confusión clima/manejo; pseudo-replicación por índices matemáticamente relacionados; predominio de Sentinel por número de columnas; resolución topográfica; interpretación excesiva de factores.\n\n## 9. Propuesta para F3.1.1 — pendiente de aprobación\n1. Mantener inicialmente los 8 índices históricos y Topography Basic, pero separar explícitamente nivel, dispersión y cobertura.\n2. Tratar `months` como calidad/soporte, no como señal estructural principal.\n3. Comparar una representación compacta por familias conceptuales contra una representación completa con pesos iguales por bloque.\n4. Considerar resúmenes anuales y métricas de estabilidad interanual, conservando la identidad anual antes de agregarlos.\n5. Imputación mediana y escalamiento robusto/estándar deben ajustarse dentro de train fold cuando exista evaluación predictiva. En descubrimiento sobre 197 parcelas, documentar claramente que el transformador es transductivo.\n6. No interpretar factores como suelo o potencial productivo sin validación externa.\n\n## 10. Decisiones pendientes\n- Aprobar si `months` entra en el espacio latente o sólo como covariable de calidad.\n- Aprobar representación completa balanceada por bloque vs resumen compacto por familias.\n- Aprobar si F3.1.1 compara resúmenes interanuales actuales con un panel anual+estabilidad.\n- Definir si el descubrimiento se ajusta sólo en TRAIN o en las 197 parcelas; para evaluación estricta se recomienda TRAIN-only y transformación de PREDICTION.\n\nNo se ejecutaron PCA, Factor Analysis, GMM, clustering, modelos, selección supervisada ni F3.1.1.\n''';(R/'f3_1_0_structural_data_audit.md').write_text(txt,encoding='utf-8')
if __name__=='__main__':main()
